CREATE OR REPLACE FUNCTION public.pay_housing() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; h public.character_housing; cost integer; d date:=(public.game_now() AT TIME ZONE 'UTC')::date; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO h FROM public.character_housing WHERE character_id=cid FOR UPDATE; IF h.last_paid_date=d OR EXISTS(SELECT 1 FROM public.economy_operations WHERE character_id=cid AND operation_key='rent:'||d AND status='done') THEN RAISE EXCEPTION 'Logement déjà payé aujourd’hui'; END IF; SELECT daily_cost INTO cost FROM public.housing_types WHERE id=h.type_id; PERFORM public.economy_cash(cid,'rent:'||d,-cost,'Logement — '||d,'logement'); UPDATE public.character_housing SET last_paid_date=d WHERE character_id=cid; END $$;
CREATE FUNCTION public.date_personal_transaction() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.world_at IS NULL THEN NEW.world_at:=public.game_now(); END IF; IF NEW.category='autres' THEN NEW.category:=CASE WHEN NEW.label LIKE 'Logement%' THEN 'logement' WHEN NEW.label='Manger' THEN 'alimentation' WHEN NEW.label LIKE 'Transport%' THEN 'transport' WHEN NEW.label LIKE 'Salaire%' THEN 'salaire' ELSE NEW.category END; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.date_personal_transaction() FROM PUBLIC;
CREATE TRIGGER personal_transaction_date BEFORE INSERT ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.date_personal_transaction();
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.personal_economy_action(text,uuid,jsonb)'::regprocedure) INTO def; def:=replace(def,'SET condition=''Bon état'',next_maintenance=t+7*interval ''1 day''','SET condition=''Bon état'',next_maintenance=t+GREATEST(1,COALESCE((cat.config->>''maintenance_days'')::integer,7))*interval ''1 day'''); EXECUTE def; END $$;